# Условный оператор if-else

Оператор `if` позволяет выполнять код только при определенном условии.

**Синтаксис:**
```dart
if (условие) {
  // код выполнится, если условие истинно
} else {
  // код выполнится, если условие ложно
}
```

**Операторы сравнения:**
- `==` - равно
- `!=` - не равно
- `>` - больше
- `<` - меньше
- `>=` - больше или равно
- `<=` - меньше или равно

**Попробуйте изменить возраст в примере →**

pages.codeSnippet:
void main() {
  int age = 18;

  if (age >= 18) {
    print('Вы совершеннолетний');
  } else {
    print('Вы несовершеннолетний');
  }

  // Множественные условия с else if
  int score = 85;

  if (score >= 90) {
    print('Оценка: Отлично!');
  } else if (score >= 75) {
    print('Оценка: Хорошо!');
  } else if (score >= 60) {
    print('Оценка: Удовлетворительно');
  } else {
    print('Оценка: Нужно подтянуться');
  }
}

void main() {
  int age = 20;
  bool hasLicense = true;

  // Оператор && (И)
  if (age >= 18 && hasLicense) {
    print('Вы можете водить машину');
  }

  // Оператор || (ИЛИ)
  String role = 'admin';
  if (role == 'admin' || role == 'moderator') {
    print('У вас есть права модератора');
  }

  // Оператор ! (НЕ)
  bool isRaining = false;
  if (!isRaining) {
    print('Можно идти гулять!');
  }

  // Комбинация операторов
  int temperature = 25;
  bool isSunny = true;

  if (temperature > 20 && temperature < 30 && isSunny) {
    print('Отличная погода для пикника!');
  }
}

void main() {
  int age = 20;

  // Обычный if-else
  String status1;
  if (age >= 18) {
    status1 = 'взрослый';
  } else {
    status1 = 'ребенок';
  }
  print('Статус (if-else): $status1');

  // То же самое с тернарным оператором
  String status2 = age >= 18 ? 'взрослый' : 'ребенок';
  print('Статус (тернарный): $status2');

  // Вложенные тернарные операторы (осторожно!)
  int score = 85;
  String grade = score >= 90 ? 'A' 
                : score >= 80 ? 'B'
                : score >= 70 ? 'C'
                : 'D';
  print('Оценка: $grade');

  // Практический пример
  int items = 3;
  print('В корзине $items ${items == 1 ? "товар" : "товара"}');
}

