# Оператор switch-case

`switch` удобен когда нужно проверить одну переменную на множество значений.

**Синтаксис:**
```dart
switch (переменная) {
  case значение1:
    // код
    break;
  case значение2:
    // код
    break;
  default:
    // код по умолчанию
}
```

**Важно:** не забывайте `break`, иначе выполнение продолжится в следующий case!

**Примеры →**

pages.codeSnippet:
void main() {
  // Пример 1: Дни недели
  int dayNumber = 3;

  switch (dayNumber) {
    case 1:
      print('Понедельник');
      break;
    case 2:
      print('Вторник');
      break;
    case 3:
      print('Среда');
      break;
    case 4:
      print('Четверг');
      break;
    case 5:
      print('Пятница');
      break;
    case 6:
    case 7:
      print('Выходной!');
      break;
    default:
      print('Некорректный номер дня');
  }

  // Пример 2: Команды
  String command = 'start';

  switch (command) {
    case 'start':
      print('Запуск программы...');
      break;
    case 'stop':
      print('Остановка программы...');
      break;
    case 'pause':
      print('Пауза...');
      break;
    default:
      print('Неизвестная команда');
  }
}

void main() {
  // Простой счетчик
  print('Счет от 1 до 5:');
  for (int i = 1; i <= 5; i++) {
    print(i);
  }

  // Обратный отсчет
  print('\nОбратный отсчет:');
  for (int i = 10; i >= 1; i--) {
    print(i);
  }
  print('Пуск!');

  // Шаг с изменением
  print('\nЧетные числа от 0 до 10:');
  for (int i = 0; i <= 10; i += 2) {
    print(i);
  }

  // Таблица умножения
  print('\nТаблица умножения на 5:');
  for (int i = 1; i <= 10; i++) {
    print('5 × $i = ${5 * i}');
  }
}

