# Итерация по коллекциям

**for-in** - удобный способ перебора элементов списка:
```dart
for (var элемент in коллекция) {
  // работа с элементом
}
```

**forEach** - метод для перебора с функцией:
```dart
коллекция.forEach((элемент) {
  // работа с элементом
});
```

**Примеры →**

pages.codeSnippet:
void main() {
  List<String> fruits = ['Яблоко', 'Банан', 'Апельсин', 'Груша'];

  // Обычный for с индексом
  print('Обычный for:');
  for (int i = 0; i < fruits.length; i++) {
    print('${i + 1}. ${fruits[i]}');
  }

  // for-in (проще!)
  print('\nFor-in:');
  for (var fruit in fruits) {
    print('- $fruit');
  }

  // forEach
  print('\nForEach:');
  fruits.forEach((fruit) {
    print('🍎 $fruit');
  });

  // Перебор Map
  Map<String, int> scores = {
    'Алиса': 95,
    'Боб': 87,
    'Карл': 92,
  };

  print('\nРезультаты:');
  scores.forEach((name, score) {
    print('$name: $score баллов');
  });
}

void main() {
  // break - выход из цикла
  print('Поиск числа 7:');
  for (int i = 1; i <= 10; i++) {
    if (i == 7) {
      print('Найдено число 7!');
      break; // прерываем цикл
    }
    print('Проверяем $i...');
  }

  // continue - пропуск итерации
  print('\nТолько четные числа:');
  for (int i = 1; i <= 10; i++) {
    if (i % 2 != 0) {
      continue; // пропускаем нечетные
    }
    print(i);
  }

  // Практический пример
  print('\nФильтрация списка:');
  List<int> numbers = [5, -3, 8, -1, 12, -7, 15];

  print('Положительные числа:');
  for (var num in numbers) {
    if (num < 0) continue; // пропускаем отрицательные
    print(num);
  }
}

// Функция без параметров и возврата
void sayHello() {
  print('Привет!');
}

// Функция с параметрами
void greet(String name) {
  print('Привет, $name!');
}

// Функция с возвратом значения
int add(int a, int b) {
  return a + b;
}

// Функция с несколькими параметрами
String getFullName(String firstName, String lastName) {
  return '$firstName $lastName';
}

// Функция для расчета
double calculateArea(double width, double height) {
  return width * height;
}

void main() {
  sayHello();

  greet('Алиса');
  greet('Боб');

  int sum = add(5, 3);
  print('5 + 3 = $sum');

  String name = getFullName('Иван', 'Иванов');
  print('Полное имя: $name');

  double area = calculateArea(5.0, 10.0);
  print('Площадь: $area');
}

// Обязательные позиционные параметры
void printSum(int a, int b) {
  print('$a + $b = ${a + b}');
}

// Необязательные позиционные параметры
String formatName(String firstName, [String? middleName, String? lastName]) {
  String result = firstName;
  if (middleName != null) result += ' $middleName';
  if (lastName != null) result += ' $lastName';
  return result;
}

// Именованные параметры
void createUser({
  required String name,
  required int age,
  String? email,
  bool isPremium = false,
}) {
  print('Пользователь: $name, $age лет');
  if (email != null) print('Email: $email');
  print('Премиум: ${isPremium ? "Да" : "Нет"}');
}

// Значения по умолчанию
int multiply(int a, [int b = 1]) {
  return a * b;
}

void main() {
  printSum(5, 3);

  print(formatName('Иван'));
  print(formatName('Иван', 'Петрович'));
  print(formatName('Иван', 'Петрович', 'Сидоров'));

  createUser(name: 'Алиса', age: 25);
  createUser(
    name: 'Боб',
    age: 30,
    email: 'bob@example.com',
    isPremium: true,
  );

  print(multiply(5));    // 5 * 1 = 5
  print(multiply(5, 3)); // 5 * 3 = 15
}

// Обычная функция
int addNormal(int a, int b) {
  return a + b;
}

// Стрелочная функция (то же самое)
int addArrow(int a, int b) => a + b;

// Другие примеры
bool isEven(int number) => number % 2 == 0;

String greet(String name) => 'Привет, $name!';

double square(double x) => x * x;

bool isAdult(int age) => age >= 18;

String getStatus(int score) => score >= 60 ? 'Сдал' : 'Не сдал';

void main() {
  print('Обычная: ${addNormal(5, 3)}');
  print('Стрелочная: ${addArrow(5, 3)}');

  print('\n10 четное? ${isEven(10)}');
  print('7 четное? ${isEven(7)}');

  print('\n${greet("Алиса")}');

  print('\nКвадрат 5: ${square(5)}');

  print('\nВозраст 20: ${isAdult(20) ? "взрослый" : "ребенок"}');
  print('Возраст 15: ${isAdult(15) ? "взрослый" : "ребенок"}');

  print('\nОценка 75: ${getStatus(75)}');
  print('Оценка 45: ${getStatus(45)}');
}

void main() {
  // Анонимная функция в forEach
  List<int> numbers = [1, 2, 3, 4, 5];

  print('Квадраты:');
  numbers.forEach((num) {
    print('$num² = ${num * num}');
  });

  // Краткая форма
  print('\nЧисла:');
  numbers.forEach((num) => print(num));

  // Замыкание - функция запоминает переменную
  Function makeMultiplier(int multiplier) {
    return (int value) => value * multiplier;
  }

  var multiplyBy2 = makeMultiplier(2);
  var multiplyBy5 = makeMultiplier(5);

  print('\n10 × 2 = ${multiplyBy2(10)}');
  print('10 × 5 = ${multiplyBy5(10)}');

  // Практический пример: счетчик
  Function makeCounter() {
    int count = 0;
    return () {
      count++;
      return count;
    };
  }

  var counter = makeCounter();
  print('\nСчетчик:');
  print(counter()); // 1
  print(counter()); // 2
  print(counter()); // 3
}

void main() {
  List<int> numbers = [1, 2, 3, 4, 5];

  // map - преобразование
  var doubled = numbers.map((n) => n * 2).toList();
  print('Удвоенные: $doubled');

  // where - фильтрация
  var evens = numbers.where((n) => n % 2 == 0).toList();
  print('Четные: $evens');

  // reduce - свертка
  var sum = numbers.reduce((a, b) => a + b);
  print('Сумма: $sum');

  // Комбинирование операций
  var result = numbers
      .where((n) => n > 2)        // фильтр: > 2
      .map((n) => n * n)          // возведение в квадрат
      .toList();
  print('Квадраты чисел > 2: $result');

  // Пример: функция, принимающая функцию
  void executeOperation(int a, int b, Function operation) {
    var result = operation(a, b);
    print('Результат: $result');
  }

  executeOperation(10, 5, (a, b) => a + b);  // Сложение
  executeOperation(10, 5, (a, b) => a - b);  // Вычитание
  executeOperation(10, 5, (a, b) => a * b);  // Умножение

  // Сортировка с компаратором
  List<String> fruits = ['банан', 'яблоко', 'апельсин', 'киви'];
  fruits.sort((a, b) => a.length.compareTo(b.length));
  print('\nПо длине: $fruits');
}

void main() {
  // Пример 1: Локальные переменные в функции
  void greet() {
    String message = 'Привет!'; // локальная переменная
    print(message);
  }

  greet();
  // print(message); // ОШИБКА! message не видна здесь

  // Пример 2: Блочная область видимости
  int x = 10;

  if (x > 5) {
    int y = 20; // y видна только внутри if
    print('x = $x, y = $y');
  }

  print('x = $x');
  // print('y = $y'); // ОШИБКА! y не видна здесь

  // Пример 3: Цикл создает свою область
  for (int i = 0; i < 3; i++) {
    int counter = i * 2; // counter создается заново на каждой итерации
    print('Итерация $i: counter = $counter');
  }

  // print(i); // ОШИБКА! i не видна вне цикла
  // print(counter); // ОШИБКА! counter не видна вне цикла

  // Пример 4: Вложенные блоки
  {
    int a = 1;
    print('Внешний блок: a = $a');

    {
      int b = 2;
      print('Внутренний блок: a = $a, b = $b'); // a видна!
    }

    // print(b); // ОШИБКА! b не видна здесь
  }
}

// Глобальные переменные (вне функций)
String appName = 'Моё приложение';
const int maxAttempts = 3;
final double pi = 3.14159;

int globalCounter = 0; // изменяемая глобальная переменная (осторожно!)

void main() {
  // Доступ к глобальным переменным
  print('Приложение: $appName');
  print('Максимум попыток: $maxAttempts');
  print('Число π: $pi');

  incrementCounter();
  incrementCounter();
  displayCounter();

  // Локальная переменная "затеняет" глобальную
  String appName = 'Локальное имя';
  print('Локальная переменная: $appName');
  // Глобальная appName всё ещё доступна, но затенена

  useConstants();
}

void incrementCounter() {
  globalCounter++; // изменяем глобальную переменную
  print('Счетчик увеличен: $globalCounter');
}

void displayCounter() {
  print('Текущее значение счетчика: $globalCounter');
}

void useConstants() {
  // Константы безопасны для глобального использования
  for (int i = 0; i < maxAttempts; i++) {
    print('Попытка ${i + 1} из $maxAttempts');
  }

  double circleArea = pi * 5 * 5;
  print('Площадь круга радиусом 5: $circleArea');
}

// Глобальная переменная
int value = 100;

void main() {
  print('Глобальная value: $value');

  // Пример 1: Параметры - это локальные переменные
  void printValue(int value) { // параметр затеняет глобальную
    print('Параметр value: $value');
    // Здесь value - это параметр, не глобальная переменная!
  }

  printValue(50);
  print('Глобальная value не изменилась: $value');

  // Пример 2: Многоуровневое затенение
  void complexExample() {
    int value = 200; // затеняет глобальную
    print('Локальная в функции: $value');

    if (true) {
      int value = 300; // затеняет локальную функции
      print('Локальная в блоке if: $value');
    }

    print('После блока if: $value'); // снова 200
  }

  complexExample();
  print('Глобальная всё ещё: $value'); // снова 100

  // Пример 3: Параметры с одинаковыми именами
  void calculate(int x, int y) {
    int result = x + y;
    print('$x + $y = $result');

    // Каждый вызов создает новые x, y, result
  }

  calculate(5, 3);
  calculate(10, 20);

  // Пример 4: Избегайте затенения для ясности
  void goodExample(int number) { // понятное имя
    int globalValue = value; // явное использование глобальной
    print('Параметр: $number, Глобальная: $globalValue');
  }

  goodExample(42);
}

void main() {
  // Пример 1: Доступ к внешним переменным
  int outerVar = 10;

  void innerFunction() {
    // Вложенная функция видит переменные main
    print('Внешняя переменная: $outerVar');
    outerVar = 20; // можем изменять!
  }

  innerFunction();
  print('После изменения: $outerVar'); // 20

  // Пример 2: Цепочка вложенных областей
  int level1 = 1;

  if (true) {
    int level2 = 2;
    print('Уровень 2: level1=$level1, level2=$level2');

    if (true) {
      int level3 = 3;
      print('Уровень 3: level1=$level1, level2=$level2, level3=$level3');

      // Можем изменять переменные из внешних областей
      level1 = 10;
      level2 = 20;
    }

    print('После уровня 3: level1=$level1, level2=$level2');
    // print(level3); // ОШИБКА! level3 не видна
  }

  // Пример 3: Вложенные функции
  void outerFunction() {
    int x = 100;

    void middleFunction() {
      int y = 200;

      void innerFunction() {
        int z = 300;
        print('Все видны: x=$x, y=$y, z=$z');
      }

      innerFunction();
      // print(z); // ОШИБКА! z не видна
    }

    middleFunction();
    // print(y); // ОШИБКА! y не видна
  }

  outerFunction();
}

void main() {
  // Пример 1: Базовое замыкание
  Function makeAdder(int addBy) {
    // addBy - переменная из внешней области
    return (int value) {
      return value + addBy; // замыкание "запомнило" addBy!
    };
  }

  var add5 = makeAdder(5);
  var add10 = makeAdder(10);

  print('10 + 5 = ${add5(10)}');   // 15
  print('10 + 10 = ${add10(10)}'); // 20

  // Пример 2: Счетчик с замыканием (приватная переменная)
  Function makeCounter() {
    int count = 0; // "приватная" переменная

    return () {
      count++; // изменяем переменную из внешней области
      return count;
    };
  }

  var counter1 = makeCounter();
  var counter2 = makeCounter(); // независимый счетчик!

  print('Счетчик 1:');
  print(counter1()); // 1
  print(counter1()); // 2
  print(counter1()); // 3

  print('Счетчик 2:');
  print(counter2()); // 1
  print(counter2()); // 2

  // Пример 3: Множитель с настройкой
  Function createMultiplier(String name, int factor) {
    int callCount = 0;

    return (int value) {
      callCount++;
      int result = value * factor;
      print('$name вызван $callCount раз: $value × $factor = $result');
      return result;
    };
  }

  var double = createMultiplier('Удвоитель', 2);
  var triple = createMultiplier('Утроитель', 3);

  double(5);
  double(10);
  triple(5);

  // Пример 4: Замыкание в цикле (частая ошибка)
  List<Function> functions = [];

  for (int i = 0; i < 3; i++) {
    functions.add(() => print('Функция $i'));
  }

  print('\nВызов функций из списка:');
  for (var func in functions) {
    func(); // Каждая функция "запомнила" свое значение i
  }
}

